const body = $json.body ?? $json;
const email = typeof body.caption_email === 'string' ? body.caption_email.trim().toLowerCase() : '';
const emailPattern = /^[a-zA-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
const imageBase64 = typeof body.image?.base64 === 'string' ? body.image.base64 : '';
const maxBase64Length = Math.ceil((10 * 1024 * 1024) * 4 / 3) + 4;
const base64Pattern = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;
if (typeof body.processing_id !== 'string' || body.processing_id.length < 1 || body.processing_id.length > 128 || typeof body.message_id !== 'string' || body.message_id.length < 1 || body.message_id.length > 256 || body.source !== 'whatsapp') throw new Error('Invalid WhatsApp event identity');
if (!emailPattern.test(email)) throw new Error('A valid email caption is required');
if (!body.image || !['image/jpeg', 'image/png', 'image/webp'].includes(body.image.mime_type) || imageBase64.length === 0 || imageBase64.length > maxBase64Length || !base64Pattern.test(imageBase64)) throw new Error('A valid image payload is required');
return [{ json: { ...body, caption_email: email, image: { ...body.image, base64: imageBase64 } } }];
